text:
{
  "title": "استمارة طلب التوظيف وإقرار معالجة البيانات - شركة الأفق الذكي للتجارة",
  "planted": [
    {
      "slot": "p1",
      "text": "تستمر الشركة في أرشيفها التاريخي بالاحتفاظ بسجلات المتقدمين وملفاتهم المهنية لأغراض التحليل الإحصائي المستقبلي ودراسات سوق العمل دون جدول زمني محدد لإلغاء هذه السجلات."
    },
    {
      "slot": "p2",
      "text": "تخضع مراجعة البيانات الشخصية أو طلب تعديلها لإجراءات إدارية داخلية تقديرية تتطلب سداد رسوم إدارية مع إمكانية رفض الطلب في حال تعارض ذلك مع التشغيل الداخلي للشركة."
    },
    {
      "slot": "p3",
      "text": "تُستثمر البيانات المتعلقة بالحالة الصحية والخلفية الاجتماعية للمرشحين ضمن حزم البيانات الموجهة لتحسين تجربة التوظيف وتوجيه الرسائل الإعلانية والعروض الترويجية المناسبة لملفاتهم."
    },
    {
      "slot": "p4",
      "text": "تقتصر حقول البيانات المطلوبة في هذا النموذج حصرياً على الاسم الثلاثي، ومعلومات التواصل الأساسية، والخبرات العملية اللازمة لتقييم الكفاءة المهنية لشغل الوظيفة المعلن عنها."
    },
    {
      "slot": "p5",
      "text": "يحق للمتقدم في أي وقت سحب موافقته السابقة على معالجة بياناته، على أن يُراعى استمرار المعالجة إذا استدعت متطلبات التشغيل الفعلي استكمال الإجراءات التنظيمية المرتبطة بالطلب."
    }
  ],
  "neutral": [
    "تخضع كافة النزاعات الناشئة عن هذا الطلب حصرياً للأنظمة المعمول بها في المملكة العربية السعودية وتختص المحاكم المختصة بالنظر فيها.",
    "تعتبر حقوق الملكية الفكرية لجميع النماذج والمستندات المقدمة من خلال هذه البوابة ملكية خالصة للشركة ولا يحق لأي طرف استخدامها دون إذن خطي مسبق.",
    "لا تتحمل الشركة أي مسؤولية مالية أو قانونية عن انقطاع الخدمة الإلكترونية الناتج عن أعطال شبكة الإنترنت أو القوة القاهرة.",
    "تتم كافة المدفوعات المالية والتعويضات المرتبطة بالخدمات عبر الحوافظ البنكية المعتمدة للشركة حصريا خلال أيام العمل الرسمية.",
    "تعتبر كافة الإشعارات والمراسلات المتبادلة بين الطرفين صحيحة ومنتجة لآثارها القانونية عند إرسالها عبر البريد الإلكتروني المسجل في الطلب."
  ]
}
